<div class="gamification-widget-matches"><?php foreach ($matches as $match): ?><a href="<?php echo url('matches/'.$match['match_id'].'/'.url_title($match['title'])) ?>"><time><?php echo utf8_htmlentities($match['starts_at'] ?? '') ?></time><strong><?php echo utf8_htmlentities($match['home_team_title'] ?: $match['home_name']) ?></strong><span><?php echo $match['score_home'] === NULL ? $this->lang('VS') : (int)$match['score_home'].' - '.(int)$match['score_away'] ?></span><strong><?php echo utf8_htmlentities($match['away_team_title'] ?: $match['away_name']) ?></strong></a><?php endforeach ?></div>
